       48→  \widetilde{w}_{-1}(s)\widetilde{w}_{-1}&=H_1(-s)H_2\left(-s^{-1} \right), \\
       49→\tag{Re:4a}
       50→  \widetilde{w}_{-1}X_{-1}(u)\widetilde{w}_{-1}^{-1}&=Y_{-1}(-u),\\
       51→\tag{Re:4b}
       52→  \widetilde{w}_{-1}Y_{-1}(u)\widetilde{w}_{-1}^{-1}&=X_{-1}(-u),\\
       53→\tag{Re:5a}
       54→  {\widetilde{w}_{-1}} H_1(s)\widetilde{w}_{-1}^{-1} &= H_2(s),\\
       55→\tag{Re:5b}
       56→  {\widetilde{w}_{-1}} H_2(s)\widetilde{w}_{-1}^{-1} &= H_1(s),\\
