       62→  H_1(s)Y_{-1}(u)H_1(s)^{-1}&=Y_{-1}\left(s^{-1}u \right),\\
       63→\tag{Re:6d}
       64→  H_2(s)Y_{-1}(u)H_2(s)^{-1}&=Y_{-1}(su),\\
       65→\intertext{Relations that define subgroups $\mathrm{GL}_2(\ell,j,k)$:}
