       67→  X_{\ell,jk}(u)X_{\ell,jk}(v)&=X_{\ell,jk}(u+v),\\
       68→\tag{Im:1b}
       69→  Y_{\ell,jk}(u)Y_{\ell,jk}(v)&=Y_{\ell,jk}(u+v),\\
