      101→  (X_{\ell,jk}(u), Y_{m,pq}(v))&=1\qquad\text{for $j\neq p$, or $k\neq q$, or $|\ell-m|>1$,}\\
      102→\tag{U:3a} (X_{1,2k}(u),Y_{0,2k}(v))&=X_

