content:         1→<informal_theorem>
        2→Prove the lemma `Xm_zero_in_G`, whose Lean statement is fixed below. It is one step in the proof of the following result; the Lean definitions in the Setting encode that result's objects and rules, and the earlier lemmas given there may be used as facts.
        3→
        4→Setting:
        5→Let $\mathbb{C}$ denote the set of complex numbers, let $\mathbb{N}$ denote the set of natural numbers.
        6→Let $c(j)$ denote  the coefficient of $q^j$ in the  modular function
        7→
        8→$$J(q)=\sum_{j\geq -1}c(j)q^j= {1 \over q}  + 196884 q + 21493760 q^2 + 864299970 q^3  + \cdots$$
        9→
       10→so that $c(-1) = 1,\ c(0) = 0,\ c(1) = 196884, \dots$
       11→
       12→Define an index set:
       13→
       14→$$E=  \left\{(\ell,j,k)\mid j\in\mathbb{N},\, 1 \leq k\leq c(j),\, 0\leq \ell<j \right\}$$
       15→
       16→Define a complex number: $$c_{\ell j} := (-1)^{\ell+1} \binom{j-1}{\ell} \, (\ell+1)(j-\ell)$$
       17→
       18→Let $\mathcal{X}$ be the set of symbols
       19→$$\mathcal{X} :=\{H_1(s), H_2(s), X_{-1}(u),  Y_{-1}(u), X_{\ell,jk}(u), Y_{\ell,jk}(u) \mid$$ 
       20→$$\qquad \qquad \qquad \qquad\qquad \qquad \qquad \qquad s\in \mathbb{C}^\times, u\in \mathbb{C}, (\ell,j,k)\in E\}.$$
       21→Let $F(\mathcal{X})$ denote the free group on~$\mathcal{X}$.
       22→
       23→We  call  $X_{-1}(u)$, $Y_{-1}(u)$, $X_{\ell,jk}(u)$ and $Y_{\ell,jk}(u)$ {\it unipotent generators}.
       24→
       25→We define $\mathcal{R}\subseteq F(\mathcal{X})$  and additional symbols $ \widetilde{w}_{-1}(s)$ and   $\widetilde{w}_{\ell,jk}(s)$ as follows, for all $s,t\in \mathbb{C}^\times$, $u,v\in \mathbb{C}$, $(\ell,j,k),(m,p,q) \in E$.\\
       26→
       27→\begingroup\allowdisplaybreaks
       28→\begin{align*}
       29→\tag{Re:0} 
       30→  \widetilde{w}_{-1}(s) &:= X_{-1}(s) Y_{-1}\left(-s^{-1} \right) X_{-1}(s), \\ \widetilde{w}_{-1} &:= \widetilde{w}_{-1}(1),\\
       31→\tag{Im:0}
       32→  \widetilde{w}_{\ell,jk}(s) &:= X_{\ell,jk}\left({s}\right) Y_{\ell,jk}\left(\frac{-s^{-1}}{{c_{\ell j}}}\right) 
       33→  X_{\ell,jk}\left({s}\right),\\  \widetilde{w}_{\ell,jk} &:= \widetilde{w}_{\ell,jk}(1),\\
       34→\intertext{Relations that define a subgroup $\mathrm{GL}_2(-1)$:}
       35→\tag{H:1a}
       36→   H_1(s)H_1(t)&=H_1(st),\\
       37→\tag{H:1b}
       38→   H_2(s)H_2(t)&=H_2(st),\\
       39→\tag{H:2}
       40→    H_1(s)H_2(t)&=H_2(t)H_1(s),\\
       41→\tag{Re:1a}
       42→   X_{-1}(u)X_{-1}(v)&=X_{-1}(u+v),\\
       43→\tag{Re:1b}
       44→   Y_{-1}(u)Y_{-1}(v)&=Y_{-1}(u+v),\\
       45→\tag{Re:2}
       46→  Y_{-1}(-t)X_{-1}(s)Y_{-1}(t)&= X_{-1}\left(-t^{-1}\right) Y_{-1}\left(-t^{2}s \right)X_{-1}\left(t^{-1} \right),\\ 
       47→\tag{Re:3}
       48→  \widetilde{w}_{-1}(s)\widetilde{w}_{-1}&=H_1(-s)H_2\left(-s^{-1} \right), \\
       49→\tag{Re:4a}
       50→  \widetilde{w}_{-1}X_{-1}(u)\widetilde{w}_{-1}^{-1}&=Y_{-1}(-u),\\
       51→\tag{Re:4b}
       52→  \widetilde{w}_{-1}Y_{-1}(u)\widetilde{w}_{-1}^{-1}&=X_{-1}(-u),\\
       53→\tag{Re:5a}
       54→  {\widetilde{w}_{-1}} H_1(s)\widetilde{w}_{-1}^{-1} &= H_2(s),\\
       55→\tag{Re:5b}
       56→  {\widetilde{w}_{-1}} H_2(s)\widetilde{w}_{-1}^{-1} &= H_1(s),\\
       57→\tag{Re:6a}
       58→  H_1(s)X_{-1}(u)H_1(s)^{-1}&=X_{-1}(su),\\
       59→\tag{Re:6b}
       60→  H_2(s)X_{-1}(u)H_2(s)^{-1}&=X_{-1}\left(s^{-1}u \right),\\
       61→\tag{Re:6c}
       62→  H_1(s)Y_{-1}(u)H_1(s)^{-1}&=Y_{-1}\left(s^{-1}u \right),\\
       63→\tag{Re:6d}
       64→  H_2(s)Y_{-1}(u)H_2(s)^{-1}&=Y_{-1}(su),\\
       65→\intertext{Relations that define subgroups $\mathrm{GL}_2(\ell,j,k)$:}
       66→\tag{Im:1a}
       67→  X_{\ell,jk}(u)X_{\ell,jk}(v)&=X_{\ell,jk}(u+v),\\
       68→\tag{Im:1b}
       69→  Y_{\ell,jk}(u)Y_{\ell,jk}(v)&=Y_{\ell,jk}(u+v),\\
       70→\tag{Im:2}
       71→  Y_{\ell,jk}(-t)X_{\ell,jk}(s)Y_{\ell,jk}(t)&= \\
       72→  \qquad \qquad X_{\ell,jk}&\left(\frac{-t^{-1}}{c_{\ell j}}\right)Y_{\ell,jk}\left(-c_{\ell j}t^2s\right)X_{\ell,jk}\left(\frac{t^{-1}}{c_{\ell j}}\right),\\
       73→\tag{Im:3}
       74→  \widetilde{w}_{\ell,jk}\left(s^{(\ell+1)(j-\ell)} \right)\widetilde{w}_{\ell,jk}&=H_1\left((-s)^{j-\ell}\right) H_2\left((-s)^{\ell+1}\right), \\
       75→\tag{Im:4a}
       76→  \widetilde{w}_{\ell,jk} X_{\ell,jk}(u) {\widetilde{w}_{\ell,jk}}^{-1}&= Y_{\ell,jk}\left(\frac{-u}{c_{\ell j}}\right),\\
       77→\tag{Im:4b}
       78→  \widetilde{w}_{\ell,jk} Y_{\ell,jk}(u) {\widetilde{w}_{\ell,jk}}^{-1}&= X_{\ell,jk}\left(-c_{\ell j}u \right),\\
       79→\tag{Im:5a}
       80→  \widetilde{w}_{\ell,jk} H_1\left(s^{j-\ell} \right) {\widetilde{w}_{\ell,jk}}^{-1}&=  H_2\left(s^{-(\ell+1)}\right),\\
       81→\tag{Im:5b}
       82→  \widetilde{w}_{\ell,jk} H_2\left(s^{\ell+1} \right) {\widetilde{w}_{\ell,jk}}^{-1}&=  H_1\left(s^{-(j-\ell)}\right),\\
       83→\tag{Im:6a}
       84→  H_1(s) X_{\ell,jk}(u) H_1(s)^{-1}&=X_{\ell,jk}\left(s^{\ell+1}u \right),\\
       85→\tag{Im:6b}
       86→  H_2(s) X_{\ell,jk}(u) H_2(s)^{-1}&=X_{\ell,jk}\left(s^{j-\ell}u \right),\\
       87→\tag{Im:6c}
       88→  H_1(s) Y_{\ell,jk}(u) H_1(s)^{-1}&=Y_{\ell,jk}\left(s^{-(\ell+1)}u \right),\\
       89→\tag{Im:6d}
       90→  H_2(s) Y_{\ell,jk}(u) H_2(s)^{-1}&=Y_{\ell,jk}\left(s^{-(j-\ell)}u \right),\\
       91→\intertext{Relations between the unipotent generators:}
       92→\tag{U:1a}
       93→  (X_{-1}(u), X_{j-1,jk}(v))&=1,\\
       94→\tag{U:1b} 
       95→  (Y_{-1}(u), Y_{j-1,jk}(v))&=1.\\
       96→\tag{U:1c}
       97→  (Y_{-1}(u), X_{0,jk}(v))&=1,\\
       98→\tag{U:1d}
       99→  (X_{-1}(u), Y_{0,jk}(v))&=1,\\
      100→\tag{U:2}
      101→  (X_{\ell,jk}(u), Y_{m,pq}(v))&=1\qquad\text{for $j\neq p$, or $k\neq q$, or $|\ell-m|>1$,}\\
      102→\tag{U:3a} (X_{1,2k}(u),Y_{0,2k}(v))&=X_

